M=read(O/'player-ready-matrix.json');C=read(O/'player-ready-campaigns.json');T=read(O/'player-ready-checks.json');B=read(O/'player-ready-baseline.json');FO=read(O/'player-ready-focused.json');EC=read(ROOT/'game/data/campaign_economy_contract.json')
