roles=[
 ['林岚','远距稳定、边走边处理伤员；抢救先于搬运','M01/M06/M09/M19','没有急救期限、伤员已稳定时，优势下降；不独占基础稳定'],
 ['许舟','用绳路跨障碍；5级可带伤员，不为全队凭空造锚点','M06/M15/M20/M23','开阔干地可直接走；不需要为显示价值堵死普通路'],
 ['苏棠','把自己的行动交到关键位置，或协调下一次移动','多点同时作业、接力撤离','5级AP转交每任务1次，原移动模式仍可用；不是全队额外生出AP'],
 ['陈砚','取消机器本轮动作，隔两格保护未毁任务装置','M02/M05/M14/M20','能提前停机/绕路时不一定需要护盾；护盾不修复设备'],
 ['叶禾','保留供电而隔离危险输出；铺绝缘通道','M05/M14/S11','要接近并花2AP；普通停机仍可用，但供电取舍不同'],
 ['贺鸣','省出担架购买与支援槽；保护射线、可靠搬运','M04/M09/M19/M23','已有担架且不需要屏障时替代性较强；不再叠搬运加速变万能'],
 ['莫遥','5格外处理已知停机开关，改机器下一轮目标','M13/M18/M22','不能远程完成主目标/资料；与叶禾保电方案互有取舍'],
 ['江朔','入队即有2格交接，5级3格；搬运时可用真实药剂','M16/M19/M23/M24撤离','中间有占位/墙/水不能交接；药剂要自己准备，普通放下接手仍免费开放']]
parts=['<section id="player-ready"><p class="muted">0.15 · 角色、经济、人物正文与操作流程 · 2026-11-03 · 暂不进入正式开发</p><h1>把培养与取舍落到实处，<br>让玩家看得懂、选得动</h1><p>本轮已写回当前方案、96场正文和离线规则。形式仍是单机俯视2D、三人小队的8×8空间战术救援；没有增加3D、联机、抽卡或新的武器动作系统。</p><nav><a href="#balance">角色平衡</a><a href="#economy">经济取舍</a><a href="#story">人物定稿</a><a href="#comfort">操作舒适度</a><a href="#evidence">验证</a><a href="character-script-final.html">读完整剧本</a></nav><div class="note"><b>本轮的“完成”：</b>具体规则与对白已补齐，并执行当前回归；不是保证所有角色同强、所有玩家满意。正式界面、最终立绘与真人游玩尚未发生，不能用自动通关代替体验验收。</div>']
parts.append('<h2 id="balance">角色：分工有机会，强度有边界</h2><p>不推迟初始角色加入，不用随机稀有度掩盖强度。较强能力靠真实等级、次数、站位、消耗与机会成本约束；任务需要的是功能，而非指定姓名。苏棠五级行动转交从共享额度内可两次改为每任务最多一次；陈砚加固距离1→2；莫遥已知开关检修4→5；江朔两格交接提前到三级，五级三格。其他四人保留各自规则，没有全员一起涨数值。</p>'+table(['人物','玩家为什么选','重点适用场景','为什么不是必选'],roles))
parts.append('<p>五级仍需72经验。江朔第16关后加入时为三级，新的两格交接当时即可用；三级普通角色不能免费得到五级能力。36关轮换培养样本中，贺鸣和莫遥到四级，江朔仍三级：把重要用途全放在他们五级会太晚，所以这次没有靠继续抬高培养成本解决弱角色的问题。</p><p>检验也区分能力和路线搜索：加入许舟携带抛索的合理路线尝试，并保留普通绕行候选；不能把搜索器以前不会用技能造成的差距当成人物弱。当前1432个阵容/目标情境在三级、五级均保留成功路线，其中'+str(len(gains))+'个五级结果优于同菜单三级。这个数混合成长与已有用途的搜索，不是“乐趣分数”或角色平衡率。</p>')
parts.append('<details><summary>江朔专项：更好的普通交接也参加比较</summary><p>12个后期关卡/阵容情境，枚举小规模目标分工，允许普通放下、接手、步行；只关掉/打开江朔本人专长，其他角色和三级一致。'+str(FO['trials'])+'条候选中，'+str(len(focus))+'个情境有额外收益。这里主要是行动余量，不能宣称带来独占结局。</p>'+table(['关卡/阵容','不用江朔专长','使用江朔专长'],[[r['mission']+' / '+'、'.join(names[a] for a in r['party']),str(r['states']['False']['rounds'])+'轮 / '+str(r['states']['False']['damage'])+'伤害 / '+str(r['states']['False']['ap'])+'AP',str(r['states']['True']['rounds'])+'轮 / '+str(r['states']['True']['damage'])+'伤害 / '+str(r['states']['True']['ap'])+'AP'] for r in focus])+'<p>六个五级大矩阵优选样本用到江朔交接，三级大矩阵的原路线菜单没有主动选它；专项分工搜索才找到上述收益。这仍说明他对站位与阵容更挑剔，不宣称已经与苏棠一样泛用。</p></details>')
parts.append('<h2 id="economy">经济：削减自动富余，提高具体目标价值</h2>'+table(['项目','之前','当前'],[['初始资金/物资/零件','60 / 8 / 2','30 / 6 / 2'],['主线成功','24 / 2 / 2','10 / 1 / 1'],['主线部分完成','14 / 1 / 1','7 / 0 / 0'],['主线失败','6 / 0 / 0','6 / 0 / 0，借调后也保留'],['支线成功','16 / 1 / 1','6 / 0 / 0，另按实物交接奖励'],['支线部分/失败资金','8 / 0','3 / 0'],['任意额外目标统一奖励','通常+1物资；S05另发2','撤销，替换22个明确目标奖励'],['医疗药剂/普通生活','1物资一剂；基本生活免费','不变；不做每人每日生存税']]))
parts.append('<p><b>具体取舍：</b>M03额外零件+3，M09医疗箱+3物资，M16额外货物+12资金，M23重建箱+3零件。S02药箱+4物资，书籍运输专项补助+12资金；买4物资需16资金，因此药品即时价值较高，资金用途更灵活。这里修掉了原候选“3物资对12资金”的完全可兑换关系。能同时带回两项就两项都给，不为制造取舍强行互斥。</p><p>M02备用件运回给2零件，现场用掉可节省供电作业，但不能再拿交回奖励。档案、隐私处理、救出更多人的选择保留事实与世界后果，不统一换成现金。全部奖励在出发前公开；只有secured交接发放，做过但已毁不发，重复结算不发。</p>')
parts.append('<p><b>可验证的预算冲突：</b>35资金、4零件时，买通信设施I就不能同时买20资金的绞盘；先买绞盘则买不起通信设施。设施四条完整路线总计380资金/48零件，再买五种非初始工具还需98资金/8零件。所有基础成功报酬与现金目标全拿的理论资金上限416（尚未支付人物费用），零件上限47；不能通过全做支线把所有设施和工具无取舍买齐。固定队伍全36关临界训练且不买设施的期末余量为402/62/47。</p><p>设施优先样本最终买到7个升级阶段，仍缺医务室II；还剩82资金却只有7零件，低于所需8。真正限制来自投资结构，而不是逼玩家在每一晚买补给。没有伤势就不推荐医务室；没有临界升级就不推荐训练；已靠普通路线解决问题，可以存钱。</p>')
parts.append('<details><summary>全部明确交接奖励</summary>'+table(['任务/对象','奖励','来源'],[[r['mission']+'/'+r['objective'],'、'.join({'credits':'资金','supplies':'物资','parts':'零件'}[k]+'+'+str(v) for k,v in r['reward'].items()),r['source']] for r in EC['objective_rewards']])+'</details>')
parts.append('<h2 id="story">人物：96场正文已补齐，情绪与去向不再靠占位句</h2><p><a href="character-script-final.html"><b>打开可筛选的完整人物剧本</b></a>：24个人节点、12关系场景、18生活短谈、24社区回访、18章节片段。个人线每个选项都有角色回应；补了条件未兑现、永久医疗离队、后续背约和未读文本，8人的外观方向、说话习惯与战场短句也已明确。</p><p>不是每个人都一直诉苦：汤、电影、工具昵称、饭盒、盆栽、舞步、旧广告和船名都用来表现相处。专业距离有完整回应，不处罚不想和解的玩家；战后转岗在最后任务之后执行，不在普通难度突然收走养成角色。</p><p>内容审核实际改掉了三类矛盾：苏棠的“后勤有人替”不能擅自写成“当天睡过觉”；江朔工资承诺不能多出账本未要求的运输核验；章节只认保全成果，M17主动隔离另有完成文本，不误写成修复失败。R06也撤掉了早已删掉的“学习接力技能”承诺。</p><p>这是中文剧本定稿基线，不是最终立绘或配音。若后续发现事实冲突或读起来拖沓，应修订正文；不能为了维护“定稿”两字保留错误。</p>')
parts.append('<h2 id="comfort">舒畅：把规则做成可操作的信息</h2>'+table(['玩家处境','现在明确的流程','不强迫的部分'],[['首次看见危险','高亮已知预告，首次规则卡可关闭；通常每关一张，M01最多三张且错开回合','只示例一种办法，绕路/普通工具/暂时放弃均可'],['准备行动','先看路径、AP、受击区、次数和拒绝原因，再确认；右键/Esc只取消选中','不能因取消而结束回合或付款'],['人物不愿配合','显示哪种动作、谁对谁、什么安全条件；同屏保留基础行动','不要求先送礼、刷关系或换掉整个人'],['买装备或训练','列实际用途、支出后余额、下一次出勤前能否升级','不自动训练、不自动购买、不用红点催促'],['失误与重伤','按实际成果结算，说明失去与保住的部分；借调/普通恢复保持可用','失败不是整局停摆，也不额外增加惩罚税'],['一晚内容太多','项目2次与短谈2次分开显示；可读摘要后选择，未读不扣关系','不要求全看54段人物内容'],['结束回合','剩AP普通提示可关，明确致命/放弃对象要确认；AP归零仍可放下或撤离','不自动跳过玩家仍能做的零AP操作'],['撤回或读档','已知战术操作在提交边界前整体回滚；环境结算/新情报/结算/隐私发布/最终分支是边界','不只回滚AP却留下关系收益，不用铁人限制代替保存设计']]))
